-- Fast lowercase index for case-insensitive and tag-stripped matching
Hotspots.BY_LOWER = {}
for name, data in pairs(Hotspots.BY_NAME) do
    Hotspots.BY_LOWER[string.lower(name)] = data
end

local function cleanHotspotName(name)
    if not name or type(name) ~= "string" then return "" end
    local s = string.gsub(name, "<[^>]+>", "")
    s = string.gsub(s, "[\194\160\160]", " ")
    s = string.match(s, "^%s*(.-)%s*$") or s
    return s
end

function Hotspots.get(name)
    if not name then return nil end
    local direct = Hotspots.BY_NAME[name]
    if direct then return direct end
    local cleaned = cleanHotspotName(name)
    if cleaned ~= name then
        local cMatch = Hotspots.BY_NAME[cleaned]
        if cMatch then return cMatch end
    end
    return Hotspots.BY_LOWER[string.lower(cleaned)]
end

function Hotspots.findMatch(rawName)
    if not rawName then return nil end
    local exact = Hotspots.get(rawName)
    if exact then return exact, rawName end
    local cleaned = cleanHotspotName(rawName)
    local lowerClean = string.lower(cleaned)
    for name, data in pairs(Hotspots.BY_NAME) do
        local lowerKey = string.lower(name)
        if lowerClean == lowerKey or string.find(lowerClean, lowerKey, 1, true) then
            return data, name
        end
    end
    return nil, cleaned
end

return Hotspots
